export const INBOX_HTML = "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex,nofollow\">\n<title>Bandeja de feedback</title>\n<style>\n:root{--bg:#f6f6f4;--card:#fff;--ink:#16181d;--muted:#5d6370;--line:#e2e2de;--acc:#e11d48;--chip:#efefeb}\n@media (prefers-color-scheme:dark){:root:not([data-theme=light]){--bg:#15171b;--card:#1e2126;--ink:#eceef1;--muted:#a2a8b3;--line:#30343b;--chip:#2a2e35}}\n:root[data-theme=dark]{--bg:#15171b;--card:#1e2126;--ink:#eceef1;--muted:#a2a8b3;--line:#30343b;--chip:#2a2e35}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif}\nheader{position:sticky;top:0;z-index:2;background:var(--bg);border-bottom:1px solid var(--line);padding:12px 16px}\nh1{font-size:18px;margin:0 0 8px}\n.bar{display:flex;flex-wrap:wrap;gap:6px;align-items:center}\n.chip{border:1px solid var(--line);background:var(--chip);color:var(--ink);border-radius:999px;padding:6px 12px;font-size:13px;cursor:pointer}\n.chip.on{background:var(--ink);color:var(--bg);border-color:var(--ink)}\nselect,textarea{font:inherit;color:var(--ink);background:var(--card);border:1px solid var(--line);border-radius:8px;padding:6px 8px}\nmain{max-width:980px;margin:0 auto;padding:16px;display:grid;gap:14px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:12px;overflow:hidden;display:grid;grid-template-columns:minmax(0,260px) 1fr}\n.card img{width:100%;height:100%;max-height:340px;object-fit:cover;object-position:top;display:block;background:var(--chip);cursor:zoom-in}\n.noimg{display:flex;align-items:center;justify-content:center;color:var(--muted);font-size:13px;background:var(--chip);min-height:120px}\n.body{padding:12px 14px;display:flex;flex-direction:column;gap:6px;min-width:0}\n.text{font-size:16px;white-space:pre-wrap;word-break:break-word}\n.meta{color:var(--muted);font-size:13px;word-break:break-word}\n.meta a{color:inherit}\n.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:auto}\n.btn{border:1px solid var(--line);background:var(--chip);color:var(--ink);border-radius:8px;padding:6px 10px;font-size:13px;cursor:pointer}\n.st-nuevo{border-left:4px solid var(--acc)}.st-en\\ curso{border-left:4px solid #d97706}.st-hecho{border-left:4px solid #16a34a;opacity:.75}.st-descartado{border-left:4px solid #9ca3af;opacity:.6}\n.empty{color:var(--muted);text-align:center;padding:40px 0}\ndialog{border:0;padding:0;background:transparent;max-width:96vw;max-height:96vh}\ndialog img{max-width:96vw;max-height:92vh;display:block;border-radius:8px}\ndialog::backdrop{background:rgba(0,0,0,.8)}\n@media (max-width:640px){.card{grid-template-columns:1fr}.card img{max-height:260px}}\n</style>\n</head>\n<body>\n<header>\n  <h1>Bandeja de feedback <span id=\"count\" class=\"meta\"></span></h1>\n  <div class=\"bar\" id=\"statusBar\"></div>\n  <div class=\"bar\" style=\"margin-top:6px\">\n    <select id=\"pageSel\" aria-label=\"Página\"><option value=\"\">Todas las páginas</option></select>\n    <button class=\"btn\" id=\"copyAll\" type=\"button\">Copiar abiertos como tareas</button>\n    <button class=\"btn\" id=\"theme\" type=\"button\" aria-label=\"Cambiar tema\">Modo claro / nocturno</button>\n  </div>\n</header>\n<main id=\"list\"><div class=\"empty\">Cargando…</div></main>\n<dialog id=\"zoom\"><img alt=\"\"></dialog>\n<script>\n(function(){\n  var API='/__feedback/api', IMG='/__feedback/img/';\n  var state={items:[],statuses:[],canEdit:false,filter:'abiertos',page:''};\n  var $=function(s){return document.querySelector(s)};\n  try{var th=localStorage.getItem('fb-theme');if(th)document.documentElement.dataset.theme=th}catch(e){}\n  $('#theme').onclick=function(){var d=document.documentElement,n=d.dataset.theme==='dark'?'light':'dark';d.dataset.theme=n;try{localStorage.setItem('fb-theme',n)}catch(e){}};\n  function esc(s){return String(s==null?'':s).replace(/[&<>\"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]})}\n  function when(iso){try{return new Date(iso).toLocaleString('es-AR',{dateStyle:'short',timeStyle:'short'})}catch(e){return iso}}\n  function visible(){return state.items.filter(function(i){\n    if(state.page&&i.path!==state.page)return false;\n    if(state.filter==='abiertos')return i.status==='nuevo'||i.status==='en curso';\n    if(state.filter==='todos')return true;\n    return i.status===state.filter;})}\n  function bars(){\n    var opts=['abiertos'].concat(state.statuses,['todos']);\n    $('#statusBar').innerHTML=opts.map(function(o){return '<button class=\"chip'+(o===state.filter?' on':'')+'\" data-f=\"'+esc(o)+'\">'+esc(o)+'</button>'}).join('');\n    var pages=Array.from(new Set(state.items.map(function(i){return i.path}))).sort();\n    $('#pageSel').innerHTML='<option value=\"\">Todas las páginas</option>'+pages.map(function(p){return '<option'+(p===state.page?' selected':'')+'>'+esc(p)+'</option>'}).join('');\n  }\n  function render(){\n    bars();\n    var v=visible();\n    $('#count').textContent='· '+v.length;\n    if(!v.length){$('#list').innerHTML='<div class=\"empty\">No hay comentarios en esta vista.</div>';return}\n    $('#list').innerHTML=v.map(function(i){\n      var sel=state.canEdit?'<select data-id=\"'+i.id+'\" aria-label=\"Estado\">'+state.statuses.map(function(s){return '<option'+(s===i.status?' selected':'')+'>'+s+'</option>'}).join('')+'</select>':'<span class=\"chip\">'+esc(i.status)+'</span>';\n      return '<article class=\"card st-'+esc(i.status)+'\">'+\n        (i.hasImage?'<img loading=\"lazy\" src=\"'+IMG+i.id+'\" alt=\"Captura marcada\" data-zoom=\"'+i.id+'\">':'<div class=\"noimg\">Sin captura</div>')+\n        '<div class=\"body\"><div class=\"text\">'+(esc(i.text)||'<em class=\"meta\">(solo marcas)</em>')+'</div>'+\n        '<div class=\"meta\"><a href=\"'+esc(/^\\/(?!\\/)/.test(i.path||'')?i.path:'#')+'\" target=\"_blank\" rel=\"noopener\">'+esc(i.path)+'</a> · '+esc(i.device)+'</div>'+\n        '<div class=\"meta\">'+esc(i.author)+' · '+when(i.createdAt)+'</div>'+\n        '<div class=\"meta\" data-detail=\"'+i.id+'\"></div>'+\n        '<div class=\"row\">'+sel+'<button class=\"btn\" data-more=\"'+i.id+'\" type=\"button\">Detalle</button><button class=\"btn\" data-copy=\"'+i.id+'\" type=\"button\">Copiar tarea</button></div></div></article>';\n    }).join('');\n  }\n  var full={};\n  function getFull(id){return full[id]?Promise.resolve(full[id]):fetch(API+'/'+id,{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(d){full[id]=d;return d})}\n  function asTask(d){\n    var lines=['- [ ] '+(d.text||'(ver marcas en la captura)').replace(/\\n+/g,' '),\n      '  Página: '+d.url, d.element&&d.element.section?'  Sección: '+d.element.section:'',\n      d.element&&d.element.selector?'  Elemento: `'+d.element.selector+'`'+(d.element.text?' (\"'+d.element.text.slice(0,80)+'\")':''):'',\n      '  Dispositivo: '+[d.device.type,d.device.os,d.device.browser,d.device.viewport].filter(Boolean).join(' · ')+(d.device.dark?' · modo oscuro':''),\n      d.hasImage?'  Captura: '+location.origin+IMG+d.id:'', '  De: '+d.author+' · '+when(d.createdAt)];\n    return lines.filter(Boolean).join('\\n');\n  }\n  function copy(txt,btn){navigator.clipboard.writeText(txt).then(function(){var o=btn.textContent;btn.textContent='Copiado';setTimeout(function(){btn.textContent=o},1500)})}\n  document.addEventListener('click',function(e){\n    var t=e.target;\n    if(t.dataset.f){state.filter=t.dataset.f;render()}\n    if(t.dataset.zoom){var z=$('#zoom');z.querySelector('img').src=IMG+t.dataset.zoom;z.showModal()}\n    if(t.closest('dialog'))$('#zoom').close();\n    if(t.dataset.more){getFull(t.dataset.more).then(function(d){\n      var box=document.querySelector('[data-detail=\"'+d.id+'\"]'),el=d.element||{};\n      box.innerHTML=[el.section?'Sección: '+esc(el.section):'',el.selector?'Elemento: <code>'+esc(el.selector)+'</code>':'',el.text?'Texto: “'+esc(el.text)+'”':'',\n        'Pantalla: '+esc(d.device.viewport)+' · '+esc(d.device.lang)+(d.device.dark?' · modo oscuro':''),'Scroll: '+d.scrollY+' px'].filter(Boolean).join('<br>')})}\n    if(t.dataset.copy){var b=t;getFull(t.dataset.copy).then(function(d){copy(asTask(d),b)})}\n  });\n  $('#copyAll').onclick=function(){var b=this,ids=state.items.filter(function(i){return i.status==='nuevo'||i.status==='en curso'}).map(function(i){return i.id});\n    Promise.all(ids.map(getFull)).then(function(ds){copy(ds.map(asTask).join('\\n\\n')||'Sin pendientes',b)})};\n  $('#pageSel').onchange=function(){state.page=this.value;render()};\n  document.addEventListener('change',function(e){\n    var s=e.target;if(!s.dataset.id)return;\n    fetch(API+'/'+s.dataset.id,{method:'PATCH',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({status:s.value})})\n      .then(function(r){if(!r.ok)throw 0;state.items.forEach(function(i){if(i.id===s.dataset.id)i.status=s.value});delete full[s.dataset.id];render()})\n      .catch(function(){alert('No se pudo cambiar el estado')});\n  });\n  fetch(API,{credentials:'same-origin'}).then(function(r){if(!r.ok)throw r.status;return r.json()}).then(function(d){\n    state.items=d.items;state.statuses=d.statuses;state.canEdit=d.canEdit;render();\n  }).catch(function(){$('#list').innerHTML='<div class=\"empty\">No se pudo cargar. ¿Entraste con tu mail autorizado?</div>'});\n})();\n</script>\n</body>\n</html>\n";
// Worker de feedback: se pone delante de los dominios de revisión (preview), inyecta el botón
// en las páginas HTML y guarda los comentarios en KV. No cambia nada del sitio en sí.

const PREFIX = '/__feedback';
const STATUSES = ['nuevo', 'en curso', 'hecho', 'descartado'];
const MAX_BODY = 4 * 1024 * 1024;

const list = (v) => (v || '').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    const enabled = list(env.ENABLED_HOSTS).includes(url.hostname);
    if (!enabled) return fetch(req);
    // ORIGIN (opcional): de dónde traer las páginas; si no está, se pasa el pedido tal cual al sitio.
    const upstream = (r) => env.ORIGIN ? fetch(new Request(env.ORIGIN + url.pathname + url.search, r)) : fetch(r);

    const user = await identify(req, env);
    if (url.pathname === PREFIX || url.pathname.startsWith(PREFIX + '/')) {
      return handle(req, env, url, user).catch((e) => json({ error: String(e && e.message || e) }, 500));
    }

    const res = await upstream(req);
    const ct = res.headers.get('content-type') || '';
    if (!ct.includes('text/html') || !canReview(user, env)) return res;
    return new HTMLRewriter()
      .on('body', { element(e) { e.append(`<script src="${PREFIX}/widget.js" defer></script>`, { html: true }); } })
      .transform(res);
  },
};

async function handle(req, env, url, user) {
  const path = url.pathname.slice(PREFIX.length) || '/';
  const m = req.method;

  if (!user) return json({ error: 'sin sesión' }, 401);

  if (path === '/widget.js' && m === 'GET') {
    if (!canReview(user, env)) return new Response('', { status: 403 });
    const cfg = { api: PREFIX + '/api', lang: env.LANG || '', color: env.COLOR || '#e11d48' };
    return new Response(`window.FB_CONFIG=${JSON.stringify(cfg)};\n${WIDGET_JS}`, {
      headers: { 'content-type': 'application/javascript; charset=utf-8', 'cache-control': 'private, max-age=300' },
    });
  }

  if (!canView(user, env)) return json({ error: 'sin permiso' }, 403);

  if (path === '/' && m === 'GET') {
    return new Response(INBOX_HTML, {
      headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store', 'x-frame-options': 'DENY', 'referrer-policy': 'same-origin' },
    });
  }

  if (path === '/api' && m === 'GET') {
    const items = [];
    let cursor;
    do {
      const r = await env.FEEDBACK.list({ prefix: 'c:', cursor });
      r.keys.forEach((k) => items.push({ id: k.name.slice(2), ...(k.metadata || {}) }));
      cursor = r.list_complete ? null : r.cursor;
    } while (cursor && items.length < 5000);
    return json({ me: user, canEdit: canEdit(user, env), statuses: STATUSES, items });
  }

  if (path === '/api' && m === 'POST') {
    if (!canReview(user, env)) return json({ error: 'sin permiso' }, 403);
    if (!sameOrigin(req, url)) return json({ error: 'origen inválido' }, 403);
    const raw = await req.text();
    if (raw.length > MAX_BODY) return json({ error: 'demasiado grande' }, 413);
    const b = JSON.parse(raw);
    const id = `${String(9999999999999 - Date.now()).padStart(13, '0')}-${crypto.randomUUID().slice(0, 8)}`;
    const image = typeof b.image === 'string' && b.image.startsWith('data:image/jpeg;base64,') ? b.image : null;
    const item = {
      id,
      author: user,
      createdAt: new Date().toISOString(),
      status: 'nuevo',
      text: str(b.text, 4000),
      url: str(b.url, 1000),
      path: str(b.path, 500),
      title: str(b.title, 200),
      scrollY: num(b.scrollY),
      element: b.element ? { selector: str(b.element.selector, 400), tag: str(b.element.tag, 20), text: str(b.element.text, 200), section: str(b.element.section, 160) } : null,
      marks: Array.isArray(b.marks) ? b.marks.slice(0, 30).map((k) => ({ x: num(k.x), y: num(k.y), w: num(k.w), h: num(k.h) })) : [],
      device: clean(b.device),
      hasImage: !!image,
      note: '',
    };
    await env.FEEDBACK.put('c:' + id, JSON.stringify(item), { metadata: meta(item) });
    // La captura se guarda ya en binario: servirla no gasta CPU en decodificar base64.
    if (image) await env.FEEDBACK.put('b:' + id, fromB64(image.slice(image.indexOf(',') + 1)));
    return json({ ok: true, id }, 201);
  }

  const one = path.match(/^\/api\/([\w-]{10,40})$/);
  if (one && m === 'GET') {
    const item = await env.FEEDBACK.get('c:' + one[1], 'json');
    return item ? json(item) : json({ error: 'no existe' }, 404);
  }
  if (one && m === 'PATCH') {
    if (!canEdit(user, env)) return json({ error: 'sin permiso' }, 403);
    if (!sameOrigin(req, url)) return json({ error: 'origen inválido' }, 403);
    const item = await env.FEEDBACK.get('c:' + one[1], 'json');
    if (!item) return json({ error: 'no existe' }, 404);
    const b = await req.json();
    if (b.status && STATUSES.includes(b.status)) item.status = b.status;
    if (typeof b.note === 'string') item.note = str(b.note, 2000);
    item.updatedAt = new Date().toISOString();
    item.updatedBy = user;
    await env.FEEDBACK.put('c:' + item.id, JSON.stringify(item), { metadata: meta(item) });
    return json({ ok: true, item });
  }

  const img = path.match(/^\/img\/([\w-]{10,40})$/);
  if (img && m === 'GET') {
    let bin = await env.FEEDBACK.get('b:' + img[1], 'arrayBuffer');
    if (!bin) {
      // Capturas viejas (base64): se convierten una vez y quedan en binario.
      const data = await env.FEEDBACK.get('i:' + img[1]);
      if (!data) return new Response('', { status: 404 });
      bin = fromB64(data.slice(data.indexOf(',') + 1));
      await env.FEEDBACK.put('b:' + img[1], bin);
    }
    return new Response(bin, { headers: { 'content-type': 'image/jpeg', 'cache-control': 'private, max-age=31536000, immutable' } });
  }

  return json({ error: 'no encontrado' }, 404);
}

// --- Permisos (todo por parámetros del Worker) ---
// REVIEWERS: quienes ven el botón y cargan comentarios. TEAM: quienes ven la bandeja y cambian estados.
// Si una lista está vacía, vale cualquier usuario que haya pasado Cloudflare Access.
function canReview(u, env) { const l = list(env.REVIEWERS); return !!u && (!l.length || l.includes(u)); }
function canEdit(u, env) { const l = list(env.TEAM); return !!u && (!l.length || l.includes(u) || list(env.REVIEWERS).includes(u)); }
function canView(u, env) { return canReview(u, env) || canEdit(u, env); }

// Usuario: lo da Cloudflare Access. Si ACCESS_TEAM y ACCESS_AUD están configurados, se verifica la firma del JWT.
async function identify(req, env) {
  // Fail closed: solo se acepta un JWT de Access con firma verificada. DEV_USER solo sirve en local (wrangler dev).
  if (!env.ACCESS_TEAM || !env.ACCESS_AUD) return env.DEV_USER || null;
  const jwt = req.headers.get('cf-access-jwt-assertion') || cookie(req, 'CF_Authorization');
  if (!jwt) return null;
  const claims = await verifyAccessJwt(jwt, env).catch(() => null);
  return claims && claims.email ? claims.email.toLowerCase() : null;
}

let certCache = null;
async function verifyAccessJwt(token, env) {
  const [h, p, s] = token.split('.');
  const header = JSON.parse(b64urlDecode(h));
  const claims = JSON.parse(b64urlDecode(p));
  if (header.alg !== 'RS256') throw new Error('alg');
  const aud = Array.isArray(claims.aud) ? claims.aud : [claims.aud];
  if (!aud.includes(env.ACCESS_AUD)) throw new Error('aud');
  if (!claims.exp || claims.exp * 1000 < Date.now()) throw new Error('exp');
  if (claims.nbf && claims.nbf * 1000 > Date.now() + 60e3) throw new Error('nbf');
  const iss = `https://${env.ACCESS_TEAM}.cloudflareaccess.com`;
  if (claims.iss !== iss) throw new Error('iss');
  if (!certCache || certCache.at < Date.now() - 3600e3) {
    const r = await fetch(`${iss}/cdn-cgi/access/certs`);
    certCache = { at: Date.now(), keys: (await r.json()).keys };
  }
  const jwk = certCache.keys.find((k) => k.kid === header.kid);
  if (!jwk) throw new Error('kid');
  const key = await crypto.subtle.importKey('jwk', jwk, { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['verify']);
  const sig = Uint8Array.from(b64urlDecode(s), (c) => c.charCodeAt(0));
  const ok = await crypto.subtle.verify('RSASSA-PKCS1-v1_5', key, sig, new TextEncoder().encode(`${h}.${p}`));
  if (!ok) throw new Error('firma');
  return claims;
}

// --- utilidades ---
function fromB64(s) {
  if (Uint8Array.fromBase64) return Uint8Array.fromBase64(s);
  const b = atob(s), out = new Uint8Array(b.length);
  for (let i = 0; i < b.length; i++) out[i] = b.charCodeAt(i);
  return out;
}
function b64urlDecode(s) { s = s.replace(/-/g, '+').replace(/_/g, '/'); while (s.length % 4) s += '='; return atob(s); }
function cookie(req, name) { const m = (req.headers.get('cookie') || '').match(new RegExp('(?:^|;\\s*)' + name + '=([^;]+)')); return m ? m[1] : null; }
function sameOrigin(req, url) { const o = req.headers.get('origin'); return !o || o === url.origin; }
function str(v, n) { return typeof v === 'string' ? v.slice(0, n) : ''; }
function num(v) { const n = Number(v); return Number.isFinite(n) ? Math.round(n) : 0; }
function clean(d) {
  if (!d || typeof d !== 'object') return {};
  const out = {};
  ['type', 'os', 'browser', 'viewport', 'screen', 'lang', 'ua'].forEach((k) => { out[k] = str(d[k], k === 'ua' ? 300 : 40); });
  out.dpr = Number(d.dpr) || 1; out.dark = !!d.dark;
  return out;
}
function meta(it) {
  // Metadata de KV (máx. 1024 bytes): lo justo para la lista de la bandeja.
  return { createdAt: it.createdAt, status: it.status, author: it.author, path: it.path.slice(0, 100), text: it.text.slice(0, 160), device: `${it.device.type || ''} · ${it.device.os || ''} · ${it.device.browser || ''}`.slice(0, 60), hasImage: it.hasImage };
}
function json(o, status = 200) { return new Response(JSON.stringify(o), { status, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' } }); }
